#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-02

# CodeRabbit harvest: read, reply to, and resolve CodeRabbit review threads on a PR.
#
# Why: measured 2026-09-02 on Yonatan-HQ/platform (last 80 PRs), CodeRabbit posted
# 65 review threads on 24 PRs; 3 were resolved, 4 outdated, and 23 of the 24 PRs
# merged with their threads still open. Reviews were produced and then expired
# because no SDLC step read them. This script is the read/write primitive that
# the create-pr "CodeRabbit harvest" phase drives.
#
# Usage:
#   coderabbit-harvest.sh <pr-number> [owner/repo]                      # read mode
#   coderabbit-harvest.sh <pr-number> [owner/repo] --unresolved         # read, open threads only
#   coderabbit-harvest.sh <pr-number> [owner/repo] --resolve <threadId>
#   coderabbit-harvest.sh <pr-number> [owner/repo] --reply <threadId> "<text>"
#
# Read mode runs ONE GraphQL query (reviewThreads, first 100) and prints a
# compact JSON array of:
#   {threadId, commentId, path, line, severity, title, body, resolved, outdated}
# filtered to threads whose first comment is authored by coderabbitai.
# severity and title are parsed from CodeRabbit's body format:
#   _<category>_ | _<emoji> Major_ | _<effort>_   (first line)
#   **Title sentence.**                          (first bold line)
# commentId is the first comment's REST databaseId, which --reply needs.
#
# Exit codes:
#   0 = success
#   1 = gh failure, thread not found, or PR has no such thread
#   2 = usage error

set -euo pipefail

# =============================================================================
# ARGUMENTS
# =============================================================================

PR_NUMBER=""
REPO=""
MODE="read"
THREAD_ID=""
REPLY_TEXT=""

usage() {
  sed -n '/^# Usage:/,/^# Exit codes:/p' "$0" | sed 's/^# \{0,1\}//' | sed '$d'
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --help|-h)
      usage
      exit 0
      ;;
    --unresolved)
      MODE="unresolved"
      shift
      ;;
    --resolve)
      MODE="resolve"
      THREAD_ID="${2:-}"
      [[ -n "$THREAD_ID" ]] || { echo "Error: --resolve needs a threadId" >&2; exit 2; }
      shift 2
      ;;
    --reply)
      MODE="reply"
      THREAD_ID="${2:-}"
      REPLY_TEXT="${3:-}"
      if [[ -z "$THREAD_ID" || -z "$REPLY_TEXT" ]]; then
        echo "Error: --reply needs a threadId and a text" >&2
        exit 2
      fi
      shift 3
      ;;
    -*)
      echo "Error: unknown option $1" >&2
      usage >&2
      exit 2
      ;;
    *)
      if [[ -z "$PR_NUMBER" && "$1" =~ ^[0-9]+$ ]]; then
        PR_NUMBER="$1"
      elif [[ -z "$REPO" && "$1" == */* ]]; then
        REPO="$1"
      else
        echo "Error: unexpected argument $1" >&2
        usage >&2
        exit 2
      fi
      shift
      ;;
  esac
done

if [[ -z "$PR_NUMBER" ]]; then
  usage >&2
  exit 2
fi

for tool in gh jq; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    echo "Error: $tool not found on PATH" >&2
    exit 1
  fi
done

if [[ -z "$REPO" ]]; then
  # gh's own stderr is left visible on purpose: a missing remote and a missing
  # login look identical once swallowed.
  if ! REPO=$(gh repo view --json nameWithOwner -q .nameWithOwner); then
    echo "Error: could not derive owner/repo from the current checkout; pass it explicitly" >&2
    exit 2
  fi
fi

OWNER="${REPO%%/*}"
NAME="${REPO#*/}"

# =============================================================================
# READ: one GraphQL query, parsed with jq
# =============================================================================

# shellcheck disable=SC2016  # GraphQL variables, not shell expansion
QUERY='query($owner: String!, $name: String!, $number: Int!) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      reviewThreads(first: 100) {
        totalCount
        nodes {
          id
          isResolved
          isOutdated
          path
          line
          startLine
          originalLine
          comments(first: 1) {
            nodes {
              databaseId
              author { login }
              body
            }
          }
        }
      }
    }
  }
}'

# Parses the body header for severity and the first bold line for the title.
# Falls back to the header line (underscores stripped) when no bold line exists.
# shellcheck disable=SC2016  # jq variables, not shell expansion
JQ_THREADS='
  .data.repository.pullRequest.reviewThreads.nodes
  | map(select((.comments.nodes[0].author.login // "") | test("^coderabbitai(\\[bot\\])?$")))
  | map(
      (.comments.nodes[0]) as $c
      | ($c.body // "") as $body
      | ($body | split("\n")) as $lines
      | ($lines[0] // "") as $header
      | {
          threadId: .id,
          commentId: $c.databaseId,
          path: .path,
          line: (.line // .startLine // .originalLine),
          severity: (($header | ascii_downcase | [scan("critical|major|minor|trivial|nitpick")] | .[0]) // "unknown"),
          title: ((
              [$lines[] | select(test("^\\*\\*.+\\*\\*\\s*$")) | sub("^\\*\\*"; "") | sub("\\*\\*\\s*$"; "")] | .[0]
            ) // ($header | gsub("_"; "") | gsub("\\s+"; " ") | ltrimstr(" ") | rtrimstr(" "))),
          body: $body,
          resolved: .isResolved,
          outdated: .isOutdated
        }
    )
'

fetch_threads() {
  local raw total
  raw=$(gh api graphql -f query="$QUERY" -F owner="$OWNER" -F name="$NAME" -F number="$PR_NUMBER")
  total=$(printf '%s' "$raw" | jq -r '.data.repository.pullRequest.reviewThreads.totalCount // 0')
  if [[ "$total" -gt 100 ]]; then
    echo "Warning: PR has $total review threads; only the first 100 were read" >&2
  fi
  printf '%s' "$raw" | jq -c "$JQ_THREADS"
}

case "$MODE" in
  read)
    fetch_threads
    ;;
  unresolved)
    fetch_threads | jq -c 'map(select(.resolved | not))'
    ;;
  resolve)
    # shellcheck disable=SC2016  # GraphQL variable, not shell expansion
    MUTATION='mutation($threadId: ID!) {
      resolveReviewThread(input: {threadId: $threadId}) {
        thread { id isResolved }
      }
    }'
    if ! RESULT=$(gh api graphql -f query="$MUTATION" -F threadId="$THREAD_ID"); then
      echo "Error: resolveReviewThread failed for $THREAD_ID (gh output above)" >&2
      exit 1
    fi
    printf '%s' "$RESULT" | jq -c '.data.resolveReviewThread.thread | {threadId: .id, resolved: .isResolved}'
    ;;
  reply)
    COMMENT_ID=$(fetch_threads | jq -r --arg t "$THREAD_ID" '.[] | select(.threadId == $t) | .commentId')
    if [[ -z "$COMMENT_ID" || "$COMMENT_ID" == "null" ]]; then
      echo "Error: thread $THREAD_ID not found among CodeRabbit threads on PR #$PR_NUMBER" >&2
      exit 1
    fi
    if ! RESULT=$(gh api --method POST \
        "repos/$OWNER/$NAME/pulls/$PR_NUMBER/comments/$COMMENT_ID/replies" \
        -f body="$REPLY_TEXT"); then
      echo "Error: reply POST failed for comment $COMMENT_ID (gh output above)" >&2
      exit 1
    fi
    printf '%s' "$RESULT" | jq -c --arg t "$THREAD_ID" '{threadId: $t, commentId: .in_reply_to_id, replyId: .id, url: .html_url}'
    ;;
esac
